import type {
  Catalog,
  GarmentAsset,
  GarmentMeasurementsCm,
  MaterialProperties,
  Product,
  RightsInfo,
} from "@/domain/catalog";
import type { GarmentAnchor } from "@/domain/bodyShape";

/**
 * DEMO catalog adapter (FR-020, FR-060).
 *
 * Every product and garment here is fictional and generated by this project
 * (scripts/generate-demo-assets.ts). No retailer data, imagery, or patterns
 * are used. A real retailer adapter would map an approved feed into the same
 * `Catalog` shape and live alongside this file.
 */

export const DEMO_RETAILER_ID = "demo";

const DEMO_RIGHTS: RightsInfo = {
  source: "Procedurally generated by scripts/generate-demo-assets.ts",
  license: "Project-internal demo content; no third-party rights",
  authorizedBy: "n/a (self-produced)",
  notes: "Fictional product. Not affiliated with any retailer.",
};

const DEMO_MATERIAL = (composition: string): MaterialProperties => ({
  composition: { value: composition, source: "demo-synthetic" },
  arealDensity: { value: null, unit: "g/m²", source: "not-captured" },
  thickness: { value: null, unit: "mm", source: "not-captured" },
  stretchWarp: { value: null, unit: "%", source: "not-captured" },
  stretchWeft: { value: null, unit: "%", source: "not-captured" },
  bendingStiffness: { value: null, source: "not-captured" },
  friction: { value: null, source: "not-captured" },
  recovery: { value: null, unit: "%", source: "not-captured" },
});

/** Garment construction kinds understood by the demo asset generator. */
export type DemoGarmentKind = "tee" | "a-line-skirt";

export interface DemoSizeSpec {
  label: string;
  measurements: GarmentMeasurementsCm;
  /** Omit the asset to demonstrate a size that is sold but not digitised (FR-022). */
  asset: "approved" | "quality-review" | "none" | "approved-missing-file";
}

export interface DemoVariantSpec {
  variantId: string;
  colorName: string;
  colorHex: string;
}

export interface DemoProductSpec {
  productId: string;
  name: string;
  kind: DemoGarmentKind;
  anchor: GarmentAnchor;
  category: Product["category"];
  description: string;
  composition: string;
  variants: DemoVariantSpec[];
  sizes: DemoSizeSpec[];
  isQaFixture?: boolean;
}

