export function demoAssetId(productId: string, variantId: string, sizeLabel: string): string {
  return `${productId}--${variantId}--${sizeLabel}`.toLowerCase();
}

/**
 * Bump when the generator's output changes so cached files are never reused.
 * r2: armholes, shaped sleeve caps, collar and hem turn-backs, `_PART` tags for conforming.
 */
export const DEMO_ASSET_REVISION = 2;

export function demoAssetUrl(assetId: string, revision = DEMO_ASSET_REVISION): string {
  return `/demo-assets/${assetId}.r${revision}.glb`;
}

function buildCatalog(): Catalog {
  const products: Product[] = [];
  const assets: GarmentAsset[] = [];

  for (const spec of DEMO_PRODUCT_SPECS) {
    products.push({
      retailerId: DEMO_RETAILER_ID,
      productId: spec.productId,
      name: spec.name,
      category: spec.category,
      description: spec.description,
      rights: DEMO_RIGHTS,
      isQaFixture: spec.isQaFixture,
      variants: spec.variants.map((v) => ({
        variantId: v.variantId,
        colorName: v.colorName,
        colorHex: v.colorHex,
        imageUrls: [],
        sizes: spec.sizes.map((s) => {
          const id = demoAssetId(spec.productId, v.variantId, s.label);
          return { label: s.label, sku: `${spec.productId}-${v.variantId}-${s.label}`.toUpperCase(), assetId: s.asset === "none" ? null : id };
        }),
      })),
    });

    for (const v of spec.variants) {
      for (const s of spec.sizes) {
        if (s.asset === "none") continue;
        const assetId = demoAssetId(spec.productId, v.variantId, s.label);
        assets.push({
          assetId,
          productId: spec.productId,
          variantId: v.variantId,
          sizeLabel: s.label,
          status: s.asset === "quality-review" ? "quality-review" : "approved",
          file: {
            url: s.asset === "approved-missing-file" ? "/demo-assets/intentionally-missing.glb" : demoAssetUrl(assetId),
            format: "glb",
            units: "m",
            upAxis: "Y",
          },
          anchor: spec.anchor,
          garmentMeasurements: s.measurements,
          garmentMeasurementsSource: "demo-synthetic",
          material: DEMO_MATERIAL(spec.composition),
          provenance: {
            creator: "generate-demo-assets.ts",
            createdAt: "2026-10-15T00:00:00.000Z",
            revision: DEMO_ASSET_REVISION,
            rights: DEMO_RIGHTS,
            validation: "unvalidated",
            limitations: ["Simplified procedural shape built from demo measurements; no real pattern, seams, or fabric data."],
          },
        });
      }
    }
  }

  return {
    retailers: [{ id: DEMO_RETAILER_ID, name: "Demo Store (fictional)", isDemo: true }],
    products,
    assets,
  };
}

export const DEMO_CATALOG: Catalog = buildCatalog();
